Lemma limbs_at_of_bytes M : forall (ws : list Z) (dst : Z),
  0 <= dst -> dst + 8 * Z.of_nat (length ws) <= 2 ^ 64 ->
  (forall i, (i < 8 * length ws)%nat -> M (Z_to_bv 64 (dst + Z.of_nat i)) = nth_error (limb_bytes ws) i) ->
  L5.limbs_at RSEGS M dst ws.
