Lemma sm_apart LB FF LK' cr A M2 V F k rs fl sp scr a n :
  ri_inv HI LB ((F, k, rs) :: FF) LK' cr A M2 V -> 0x7fff80000000 <= ar_sptop ar <= 2 ^ 47 -> In k [0; 1; 2; 3; 4; 5] ->
  0x698000 <= F -> F + ff_bytes k <= ahl_ceil ar -> app_mem F (ff_bytes k) -> F mod ff_bytes k = 0 ->
