  ~ aclient L ar LB ((F, k, rs) :: FF) 0 0 fl ->
  (forall i, 0 <= i < n -> aclient L ar LB FF sp scr (a + i)) -> 0 < n ->
  (a + n <= F \/ F + ff_bytes k <= a) /\ (a + n <= F / 8 + SB \/ F / 8 + SB + ff_bytes k / 8 <= a) /\ (a + n <= fl \/ fl + 1 <= a).
